CREATE TABLE businesses (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL);
CREATE TABLE memberships (business_id uuid REFERENCES businesses, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('admin','operator','viewer')), status text NOT NULL CHECK(status IN ('active','disabled')), PRIMARY KEY(business_id,user_id));
CREATE TABLE invoices (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES businesses, reference text NOT NULL, funding_minor bigint NOT NULL CHECK(funding_minor BETWEEN 100 AND 1000000000), status text NOT NULL CHECK(status IN ('Draft','Pending payment','Funded','Routing','Settled','Failed')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,id));
CREATE UNIQUE INDEX invoice_reference ON invoices(business_id,lower(reference));
CREATE INDEX invoice_list ON invoices(business_id,created_at DESC);
CREATE TABLE payments (id uuid PRIMARY KEY, business_id uuid NOT NULL, invoice_id uuid NOT NULL UNIQUE, provider text NOT NULL CHECK(provider='simulation'), provider_reference text UNIQUE NOT NULL, funding_minor bigint NOT NULL CHECK(funding_minor>0), received_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,invoice_id) REFERENCES invoices(business_id,id));
CREATE TABLE quotes (id uuid PRIMARY KEY, business_id uuid NOT NULL, invoice_id uuid NOT NULL, source text NOT NULL CHECK(source='simulation-fixed-525'), simulated boolean NOT NULL CHECK(simulated), data jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,invoice_id) REFERENCES invoices(business_id,id), UNIQUE(business_id,invoice_id,id));
CREATE TABLE settlements (id uuid PRIMARY KEY, business_id uuid NOT NULL, invoice_id uuid NOT NULL UNIQUE, quote_id uuid NOT NULL, route_id text NOT NULL CHECK(route_id IN ('direct','split','multi')), expected_minor bigint NOT NULL CHECK(expected_minor>=0), minimum_minor bigint NOT NULL CHECK(minimum_minor>=0 AND minimum_minor<=expected_minor), actual_minor bigint CHECK(actual_minor>=minimum_minor), transaction_hash text CHECK(transaction_hash IS NULL), status text NOT NULL CHECK(status IN ('Routing','Settled','Failed')), created_at timestamptz NOT NULL DEFAULT now(), settled_at timestamptz, FOREIGN KEY(business_id,invoice_id,quote_id) REFERENCES quotes(business_id,invoice_id,id));
CREATE TABLE payment_events (id uuid PRIMARY KEY, business_id uuid NOT NULL, invoice_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users, correlation_id uuid NOT NULL, kind text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,invoice_id) REFERENCES invoices(business_id,id));
CREATE INDEX event_history ON payment_events(business_id,invoice_id,created_at);
CREATE FUNCTION deny_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Events are append only'; END $$;
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON payment_events FOR EACH ROW EXECUTE FUNCTION deny_event_mutation();
CREATE TABLE idempotency (business_id uuid NOT NULL REFERENCES businesses, key text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,key));
CREATE TABLE rate_limits (identity text PRIMARY KEY, window_start timestamptz NOT NULL, hits integer NOT NULL);
